// ---- stand-ins for the Windows / game environment ----
typedef unsigned int DWORD;           // 32-bit on MSVC
static DWORD g_tick = 1;
// Advances 5 s per call so the code's once-a-second warning rate limiter always logs.
static DWORD GetTickCount() { g_tick += 5000; return g_tick; }

static std::vector<std::string> g_logs;
static std::string g_sent;            // last message passed to SendMessage (serialized)
static int g_sentCount = 0;

class CvConnectionService
{
public:
	enum LogLevel { LOG_DEBUG = 0, LOG_INFO = 1, LOG_WARNING = 2, LOG_ERROR = 3 };
	CvConnectionService() : m_pMainThreadWriteBuffer(0) {}
	void Log(LogLevel level, const char* msg) { std::string s(1, "DIWE"[level]); g_logs.push_back(s + ": " + (msg ? msg : "(null)")); }
	int SendMessage(const ArduinoJson::DynamicJsonDocument& message)
	{
		g_sent.clear(); ArduinoJson::serializeJson(message, g_sent); g_sentCount++; return 0;
	}
	void ConvertJsonToLuaValue(lua_State* L, const ArduinoJson::JsonVariant& value, int iDepth = 0);
	void ProcessLuaResult(lua_State* L, int executionResult, const char* id, int iStackBase);
	void ConvertLuaToJsonValue(lua_State* L, int index, ArduinoJson::JsonVariant parent, const char* key, int iDepth = 0);
	void ConvertLuaValuesInDocument(lua_State* L, int firstIndex, int numValues, ArduinoJson::DynamicJsonDocument& parent, const char* key);
	std::string CleanLuaErrorMessage(const char* errorMsg);
	ArduinoJson::DynamicJsonDocument* m_pMainThreadWriteBuffer;
};
using namespace ArduinoJson;
