// ---- test framework: one forked child per test, output shown only on failure ----
static bool g_failed = false;
static bool g_verbose = false;
#define FAIL(...) do { printf("FAIL: "); printf(__VA_ARGS__); printf("\n"); g_failed = true; } while (0)
#define KNOWN(...) do { printf("KNOWN: "); printf(__VA_ARGS__); printf("\n"); } while (0)

static std::string trunc(const std::string& s, size_t n = 160)
{
	std::string o;
	for (size_t i = 0; i < s.size() && o.size() < n; i++) { unsigned char c = s[i]; if (c < 32 || c > 126) { char b[8]; sprintf(b, "\\x%02x", c); o += b; } else o += (char)c; }
	if (s.size() > n) { char b[40]; sprintf(b, "...(%lu bytes)", (unsigned long)s.size()); o += b; }
	return o;
}
static std::string rep(const std::string& s, int n) { std::string r; r.reserve(s.size() * n); for (int i = 0; i < n; i++) r += s; return r; }
static std::string itos(long v) { std::ostringstream o; o << v; return o.str(); }
static bool contains(const std::string& h, const std::string& n) { return h.find(n) != std::string::npos; }
static bool warned(const char* what) { for (size_t i = 0; i < g_logs.size(); i++) if (contains(g_logs[i], what)) return true; return false; }

static bool validUtf8(const std::string& s)
{
	size_t i = 0, n = s.size();
	while (i < n) {
		unsigned char c = s[i]; int len = c < 0x80 ? 1 : (c >> 5) == 6 ? 2 : (c >> 4) == 14 ? 3 : (c >> 3) == 30 ? 4 : 0;
		if (!len || i + len > n) return false;
		for (int k = 1; k < len; k++) if (((unsigned char)s[i + k] >> 6) != 2) return false;
		if (len == 2 && c < 0xC2) return false;
		i += len;
	}
	return true;
}
// JSON validity for the output: valid UTF-8 and no raw control characters
static bool validJsonText(const std::string& s)
{
	if (!validUtf8(s)) return false;
	for (size_t i = 0; i < s.size(); i++) if ((unsigned char)s[i] < 0x20) return false;
	return true;
}

struct Conv { std::string json; bool overflowed; bool luaerr; std::string err; int top0, top1; };

static lua_State* newState() { lua_State* L = luaL_newstate(); luaL_openlibs(L); return L; }

// Run a chunk with real Lua (all returns kept), convert all returns like ProcessLuaResult does
// (document already holds "type"), serialize doc["result"], and report stack tops around the conversion.
static Conv convert(const char* chunk, size_t cap = 524288, bool withType = true)
{
	Conv r; r.overflowed = false; r.luaerr = false; r.top0 = r.top1 = 0;
	g_logs.clear();
	lua_State* L = newState();
	if (luaL_loadstring(L, chunk) || lua_pcall(L, 0, LUA_MULTRET, 0)) {
		r.luaerr = true; const char* e = lua_tostring(L, -1); r.err = e ? e : "?"; lua_close(L); return r;
	}
	int n = lua_gettop(L);
	DynamicJsonDocument doc(cap);
	if (withType) doc["type"] = "t";
	r.top0 = lua_gettop(L);
	g_svc.ConvertLuaValuesInDocument(L, 1, n, doc, "result");
	r.top1 = lua_gettop(L);
	r.overflowed = doc.overflowed();
	if (withType) serializeJson(doc["result"], r.json); else serializeJson(doc, r.json);
	lua_close(L);
	return r;
}

// ---- table-driven simple cases ----
enum Kind { EQ, HAS, KNOWN_EQ, NUMRT, UTF8OK, JSONOK };
struct Case { const char* name; const char* chunk; const char* expect; Kind kind; };
static std::vector<Case>& cases() { static std::vector<Case> v; return v; }
static std::vector<std::string>& caseStore() { static std::vector<std::string> v; return v; }
struct CaseReg { CaseReg(const Case& c) { cases().push_back(c); } };

static void runCase(const Case& c)
{
	Conv r = convert(c.chunk);
	if (r.luaerr) { FAIL("[%s] Lua chunk failed: %s", c.name, r.err.c_str()); return; }
	if (r.top0 != r.top1) FAIL("[%s] Lua stack leak: top %d -> %d  input: %s", c.name, r.top0, r.top1, c.chunk);
	if (r.overflowed) FAIL("[%s] unexpected overflow", c.name);
	const std::string& j = r.json;
	switch (c.kind) {
	case EQ: if (j != c.expect) FAIL("[%s] input: %s | expected %s | got %s", c.name, c.chunk, trunc(c.expect).c_str(), trunc(j).c_str()); break;
	case KNOWN_EQ: if (j != c.expect) KNOWN("[%s] input: %s | ideal %s | got %s", c.name, c.chunk, trunc(c.expect).c_str(), trunc(j).c_str()); break;
	case HAS: {
		std::string parts = c.expect; size_t p = 0;
		while (p <= parts.size()) { size_t q = parts.find('|', p); if (q == std::string::npos) q = parts.size();
			std::string part = parts.substr(p, q - p);
			if (!contains(j, part)) FAIL("[%s] input: %s | missing %s | got %s", c.name, c.chunk, trunc(part).c_str(), trunc(j).c_str());
			p = q + 1; }
		break; }
	case UTF8OK: if (!validJsonText(j)) KNOWN("[%s] input: %s | output is not valid JSON text (raw invalid UTF-8 / control bytes): %s", c.name, c.chunk, trunc(j).c_str()); break;
	case JSONOK: if (!validJsonText(j)) KNOWN("[%s] input: %s | output is not valid JSON text: %s", c.name, c.chunk, trunc(j).c_str()); break;
	case NUMRT: {
		// compare Lua's own value against what the JSON says
		lua_State* L = newState(); luaL_dostring(L, c.chunk); double v = lua_tonumber(L, -1); lua_close(L);
		double got = strtod(j.c_str(), 0);
		bool same = (v != v) ? (j == "null") : ((v - v) != 0 ? (j == "null") : (got == v && j != "null"));
		if (!same) KNOWN("[%s] input: %s | Lua value %.17g | JSON %s", c.name, c.chunk, v, j.c_str());
		break; }
	}
}

#define C(name, chunk, expect, kind) static CaseReg cr_##name(Case{#name, chunk, expect, kind});
// (C++98: no brace init; use helper below instead)
#undef C
static CaseReg* addCase(const char* name, const char* chunk, const char* expect, Kind kind)
{
	Case c; c.name = name; c.chunk = chunk; c.expect = expect; c.kind = kind; return new CaseReg(c);
}
static void addCaseS(const std::string& name, const std::string& chunk, const std::string& expect, Kind kind)
{
	caseStore().push_back(name); caseStore().push_back(chunk); caseStore().push_back(expect);
	// stable c_str pointers are fixed up at run time via registry below
	Case c; c.name = 0; c.chunk = 0; c.expect = 0; c.kind = kind; cases().push_back(c);
}

