struct TestReg { TestReg(const char* n, void (*f)()) { Test t; t.name = n; t.fn = f; t.caseIdx = -1; tests().push_back(t); } };
#define TEST(n) static void n(); static TestReg reg_##n(#n, n); static void n()

static void nestCases();   // defined below

