// ===== nesting =====
static void registerNestCases()
{
	int depths[] = { 31, 32, 33, 34, 100 };
	for (int k = 0; k < 5; k++) {
		int N = depths[k];
		std::string chunkA = "local t={} local c=t for i=2," + itos(N) + " do local n={} c[1]=n c=n end return t";
		std::string chunkM = "local t={} local c=t for i=2," + itos(N) + " do local n={} c.a=n c=n end return t";
		std::string expA, expM;
		if (N <= 32) { expA = rep("[", N - 1) + "{}" + rep("]", N - 1); expM = rep("{\"a\":", N - 1) + "{}" + rep("}", N - 1); }
		else { expA = rep("[", 32) + "\"<too deep>\"" + rep("]", 32); expM = rep("{\"a\":", 32) + "\"<too deep>\"" + rep("}", 32); }
		addCaseS("nest_array_" + itos(N), chunkA, expA, EQ);
		addCaseS("nest_map_" + itos(N), chunkM, expM, EQ);
	}
	addCaseS("self_ref_map", "local t={} t.a=t return t", rep("{\"a\":", 32) + "\"<too deep>\"" + rep("}", 32), EQ);
	addCaseS("self_ref_array", "local t={} t[1]=t return t", rep("[", 32) + "\"<too deep>\"" + rep("]", 32), EQ);
	addCaseS("mutual_ref", "local a,b={},{} a.x=b b.x=a return a", rep("{\"x\":", 32) + "\"<too deep>\"" + rep("}", 32), EQ);
	addCaseS("mutual_ref_array", "local a,b={},{} a[1]=b b[1]=a return a", rep("[", 32) + "\"<too deep>\"" + rep("]", 32), EQ);
	addCaseS("self_ref_in_value_slot", "local t={n=1} t.self=t return t", "<too deep>|\"n\":1", HAS);
	addCaseS("self_ref_as_key", "local t={} t[t]=1 return t", "{\"<table>\":1}", EQ);
	addCaseS("deep_returns_multi", "local t={} local c=t for i=2,40 do local n={} c[1]=n c=n end return t,t", "<too deep>", HAS);
}

TEST(self_ref_work_explosion)
{
	// Two self-references per level: depth cap bounds depth but not total work (2^32 visits).
	// The doc overflows after ~20k nodes but the conversion keeps walking. Expect to finish fast.
	Conv r = convert("local t={} t.a=t t.b=t return t");
	if (r.luaerr) { FAIL("lua error %s", r.err.c_str()); return; }
	printf("finished, overflowed=%d\n", (int)r.overflowed);
}
TEST(self_ref_work_explosion_array3)
{
	Conv r = convert("local t={} t[1]=t t[2]=t t[3]=t return t");
	if (r.luaerr) { FAIL("lua error %s", r.err.c_str()); return; }
	printf("finished, overflowed=%d\n", (int)r.overflowed);
}
TEST(shared_dag_work)
{
	// Not a cycle: a legitimate DAG, each level referenced twice (2^20 paths, 20 levels)
	Conv r = convert("local t={} for i=1,20 do t={a=t,b=t} end return t");
	if (r.luaerr) { FAIL("lua error %s", r.err.c_str()); return; }
	printf("finished, overflowed=%d\n", (int)r.overflowed);
}

// ===== big strings =====
TEST(string_1MB)
{
	Conv r = convert("return string.rep('a', 1024*1024)");
	if (r.json.size() != 1024 * 1024 + 2) FAIL("1MB string: json size %lu", (unsigned long)r.json.size());
	if (r.overflowed) FAIL("1MB string overflowed doc (strings are stored by pointer, should not)");
	if (r.top0 != r.top1) FAIL("stack leak");
}
TEST(string_10MB)
{
	Conv r = convert("return string.rep('a', 10*1024*1024)");
	if (r.json.size() != 10 * 1024 * 1024 + 2) FAIL("10MB string: json size %lu", (unsigned long)r.json.size());
	if (r.overflowed) FAIL("10MB string overflowed doc");
}
TEST(string_1MB_escapes)
{
	Conv r = convert("return string.rep('\\n\"', 512*1024)");
	if (r.json.size() != 1024 * 1024 * 2 + 2 + 1024 * 1024 * 2 - 1024 * 1024 * 0 - 2 * 0 - 2) {
		// each char escapes to 2 bytes: 1M chars -> 2M bytes + quotes
		if (r.json.size() != 2 * 1024 * 1024 + 2) FAIL("escaped 1MB: json size %lu", (unsigned long)r.json.size());
	}
}
TEST(many_strings_in_array)
{
	Conv r = convert("local t={} for i=1,3000 do t[i]=string.rep('z',1000)..i end return t");
	if (r.overflowed) FAIL("3000 strings overflowed");
	if (r.json.size() < 3000 * 1000) FAIL("size %lu", (unsigned long)r.json.size());
}

// ===== metatables never called (counter check) =====
TEST(metatable_counter)
{
	lua_State* L = newState();
	const char* chunk =
		"called=0 local mt={__index=function() called=called+1 return 1 end,__newindex=function() called=called+1 end,"
		"__len=function() called=called+1 return 3 end,__pairs=function() called=called+1 end,__ipairs=function() called=called+1 end,"
		"__tostring=function() called=called+1 return 'x' end,__call=function() called=called+1 end,__eq=function() called=called+1 end,"
		"__gc=function() end} "
		"local t=setmetatable({1,2,3,a=setmetatable({5},mt)},mt) local u=setmetatable({7,8},mt) return t,u,{[setmetatable({},mt)]=setmetatable({},mt)}";
	if (luaL_loadstring(L, chunk) || lua_pcall(L, 0, LUA_MULTRET, 0)) { FAIL("chunk: %s", lua_tostring(L, -1)); return; }
	int n = lua_gettop(L);
	DynamicJsonDocument doc(524288); doc["type"] = "t";
	g_svc.ConvertLuaValuesInDocument(L, 1, n, doc, "result");
	lua_getglobal(L, "called"); int called = (int)lua_tonumber(L, -1); lua_pop(L, 1);
	if (called != 0) FAIL("metamethods were called %d times", called);
	if (lua_gettop(L) != n) FAIL("stack leak");
	lua_close(L);
}

// ===== lightuserdata + stack manipulation =====
TEST(lightuserdata_and_negative_index)
{
	lua_State* L = newState();
	int x = 0;
	lua_pushlightuserdata(L, &x);
	lua_newtable(L); lua_pushlightuserdata(L, &x); lua_pushinteger(L, 1); lua_rawset(L, -3);
	DynamicJsonDocument doc(4096); doc["type"] = "t";
	g_svc.ConvertLuaValuesInDocument(L, 1, 2, doc, "result");
	std::string j; serializeJson(doc["result"], j);
	if (j != "[\"<userdata>\",{\"<userdata>\":1}]") FAIL("got %s", trunc(j).c_str());
	// relative index use, as ForwardGameEvent does (-1 / -2)
	DynamicJsonDocument d2(4096); d2["type"] = "t";
	lua_pushnumber(L, 5); lua_pushstring(L, "s");
	g_svc.ConvertLuaToJsonValue(L, -2, d2.as<JsonObject>(), "extraPayload");
	g_svc.ConvertLuaToJsonValue(L, -1, d2.as<JsonObject>(), "visibility");
	j.clear(); serializeJson(d2, j);
	if (j != "{\"type\":\"t\",\"extraPayload\":5,\"visibility\":\"s\"}") FAIL("neg index: %s", trunc(j).c_str());
	if (lua_gettop(L) != 4) FAIL("stack top %d", lua_gettop(L));
	lua_close(L);
}

// ===== fresh (non-object) document: single value is silently dropped? =====
TEST(single_value_into_fresh_doc)
{
	Conv r = convert("return 1", 4096, false);
	if (r.json != "{\"result\":1}") KNOWN("ConvertLuaValuesInDocument(1 value) into a fresh doc with no members: ideal {\"result\":1}, got %s (callers always pre-set members, so this is only a latent trap)", trunc(r.json).c_str());
	Conv r2 = convert("return 1,2", 4096, false);
	if (r2.json != "{\"result\":[1,2]}") FAIL("2 values fresh doc: %s", trunc(r2.json).c_str());
	Conv r3 = convert("return", 4096, false);
	if (r3.json != "{\"result\":null}") FAIL("0 values fresh doc: %s", trunc(r3.json).c_str());
}

