// ===== ProcessLuaResult (RESULT_TOO_LARGE etc.) =====
struct PR { std::string sent; int topAfter; int baseVals; bool baseIntact; };
static PR processResult(const char* chunk, int baseN, bool expectOk = true)
{
	PR p; p.baseIntact = true;
	g_logs.clear(); g_sent.clear();
	lua_State* L = newState();
	for (int i = 0; i < baseN; i++) lua_pushinteger(L, 1000 + i);
	int base = lua_gettop(L);
	luaL_loadstring(L, chunk);
	int res = lua_pcall(L, 0, LUA_MULTRET, 0);
	if (!g_svc.m_pMainThreadWriteBuffer) g_svc.m_pMainThreadWriteBuffer = new DynamicJsonDocument(524288);
	g_svc.ProcessLuaResult(L, res, "id1", base);
	p.sent = g_sent; p.topAfter = lua_gettop(L); p.baseVals = base;
	for (int i = 0; i < baseN; i++) if (lua_tointeger(L, i + 1) != 1000 + i) p.baseIntact = false;
	lua_close(L);
	(void)expectOk;
	return p;
}
static void checkPR(const char* what, const PR& p, const char* mustHave)
{
	if (p.topAfter != p.baseVals) FAIL("[%s] stack top %d, expected base %d", what, p.topAfter, p.baseVals);
	if (!p.baseIntact) FAIL("[%s] values below the base were modified/popped", what);
	if (mustHave && !contains(p.sent, mustHave)) FAIL("[%s] response missing %s: %s", what, mustHave, trunc(p.sent).c_str());
}
TEST(process_result_small)
{
	checkPR("0 results", processResult("return", 0), "\"success\":true");
	checkPR("1 result base3", processResult("return {a=1}", 3), "\"result\":{\"a\":1}");
	checkPR("2 results base2", processResult("return 1,'x'", 2), "\"result\":[1,\"x\"]");
	checkPR("50 results", processResult("local t={} for i=1,50 do t[i]=i end return unpack(t)", 5), "\"success\":true");
	checkPR("500 results", processResult("local t={} for i=1,500 do t[i]=i end return unpack(t)", 5), "\"success\":true");
}
TEST(process_result_too_large_array)
{
	PR p = processResult("local t={} for i=1,200000 do t[i]=i end return t", 2);
	checkPR("200k array", p, "RESULT_TOO_LARGE");
	if (!contains(p.sent, "\"success\":false")) FAIL("too-large response not success:false: %s", trunc(p.sent).c_str());
	if (!warned("Result too large")) FAIL("no 'Result too large' log");
}
TEST(process_result_too_large_map_of_tables)
{
	PR q = processResult("local t={} for i=1,9000 do t['k'..i]={i} end return t", 1);
	checkPR("40k map of tables", q, "RESULT_TOO_LARGE");
}
TEST(process_result_too_large_multi)
{
	PR s = processResult("local t={} for i=1,600 do t[i]={i,i} end return unpack(t)", 1);
	checkPR("600 multi values", s, "success");
}
static double timeConvert(int n, bool tables, bool* overflowed)
{
	std::string chunk = std::string("local t={} for i=1,") + itos(n) + (tables ? " do t['key'..i]={i} end return t" : " do t['key'..i]=i end return t");
	clock_t c0 = clock(); Conv r = convert(chunk.c_str()); clock_t c1 = clock();
	*overflowed = r.overflowed;
	return 1000.0 * (c1 - c0) / CLOCKS_PER_SEC;
}
TEST(perf_string_key_map)
{
	// object member insertion is a linear key search in ArduinoJson: cost per map is quadratic in the key count
	int ns[] = { 1000, 4000, 8000, 16000, 0 };
	for (int i = 0; ns[i]; i++) {
		bool ov; double ms = timeConvert(ns[i], false, &ov);
		printf("map of %d string keys (int values): %.0f ms (sanitizer build), overflowed=%d\n", ns[i], ms, (int)ov);
		if (ms > 3000) KNOWN("%d-key string map takes %.0f ms in the sanitizer build (quadratic key lookup in ArduinoJson; overflow does not stop the loop)", ns[i], ms);
	}
}
TEST(perf_string_key_map_of_tables)
{
	int ns[] = { 1000, 4000, 8000, 16000, 0 };
	for (int i = 0; ns[i]; i++) {
		bool ov; double ms = timeConvert(ns[i], true, &ov);
		printf("map of %d string keys (table values): %.0f ms (sanitizer build), overflowed=%d\n", ns[i], ms, (int)ov);
		if (ms > 3000) KNOWN("%d-key map of tables takes %.0f ms in the sanitizer build", ns[i], ms);
	}
}
TEST(process_result_too_large_boundary)
{
	// just under / over the limit on this arch
	int lo = 1, hi = 400000;
	while (lo < hi) {
		int mid = (lo + hi + 1) / 2;
		std::string chunk = "local t={} for i=1," + itos(mid) + " do t[i]=i end return t";
		PR p = processResult(chunk.c_str(), 0);
		if (contains(p.sent, "RESULT_TOO_LARGE")) hi = mid - 1; else lo = mid;
	}
	std::string chunk = "local t={} for i=1," + itos(lo) + " do t[i]=i end return t";
	PR ok = processResult(chunk.c_str(), 0);
	if (!contains(ok.sent, "\"success\":true") || ok.sent.size() < (size_t)lo * 2) FAIL("boundary %d not a full success", lo);
	// the boundary response must hold all elements
	if (!contains(ok.sent, "," + itos(lo) + "]")) FAIL("boundary %d response truncated: ...%s", lo, trunc(ok.sent.substr(ok.sent.size() > 40 ? ok.sent.size() - 40 : 0)).c_str());
}
TEST(process_result_errors)
{
	PR a = processResult("error('boom')", 2);
	checkPR("error string", a, "\"success\":false");
	if (!contains(a.sent, "boom")) FAIL("error text missing: %s", trunc(a.sent).c_str());
	PR b = processResult("error({code=1})", 2);
	checkPR("error table", b, "Unknown Lua error");
	PR c = processResult("error(setmetatable({}, {__tostring=function() return 'x' end}))", 0);
	checkPR("error object w/ tostring", c, "\"success\":false");
	PR d = processResult("error()", 0);
	checkPR("error nil", d, "\"success\":false");
	PR e = processResult("error('a:b:c: msg')", 0);
	checkPR("error with colons", e, "\"success\":false");
}
TEST(process_result_big_string)
{
	PR p = processResult("return string.rep('q', 10*1024*1024)", 1);
	checkPR("10MB string", p, "\"success\":true");
	if (p.sent.size() < 10 * 1024 * 1024) FAIL("10MB response truncated: %lu", (unsigned long)p.sent.size());
}
TEST(process_result_nested_cap)
{
	PR p = processResult("local t={} local c=t for i=2,40 do local n={} c[1]=n c=n end return t,5", 0);
	checkPR("deep + extra value", p, "<too deep>");
}

// ===== lifetime: does the doc copy Lua strings? =====
static std::vector<void*> g_quarantine;
static void* qalloc(void*, void* ptr, size_t osize, size_t nsize)
{
	if (nsize == 0) { if (ptr) { memset(ptr, 0xA5, osize ? osize - 1 : 0); if (osize) ((char*)ptr)[osize - 1] = 0; g_quarantine.push_back(ptr); } return 0; }
	if (!ptr) return malloc(nsize);
	void* n = malloc(nsize); memcpy(n, ptr, osize < nsize ? osize : nsize);
	memset(ptr, 0xA5, osize ? osize - 1 : 0); if (osize) ((char*)ptr)[osize - 1] = 0; g_quarantine.push_back(ptr);
	return n;
}
static void lifetimeCheck(const char* what, const char* chunk, bool expectCopied)
{
	lua_State* L = lua_newstate(qalloc, 0); luaL_openlibs(L);
	if (luaL_loadstring(L, chunk) || lua_pcall(L, 0, LUA_MULTRET, 0)) { FAIL("[%s] chunk: %s", what, lua_tostring(L, -1)); return; }
	int n = lua_gettop(L);
	DynamicJsonDocument doc(65536); doc["type"] = "t";
	g_svc.ConvertLuaValuesInDocument(L, 1, n, doc, "result");
	std::string before; serializeJson(doc["result"], before);   // what the DLL does (serialize while values are on the stack)
	lua_settop(L, 0); lua_gc(L, LUA_GCCOLLECT, 0); lua_gc(L, LUA_GCCOLLECT, 0);
	std::string after; serializeJson(doc["result"], after);     // what would happen if Lua popped first
	bool same = (before == after);
	if (g_verbose || !same) printf("[%s] serialize-before-pop: %s | after pop+GC: %s\n", what, trunc(before, 100).c_str(), trunc(after, 100).c_str());
	if (expectCopied && !same) FAIL("[%s] expected the doc to own a copy but it changed after the Lua value was collected", what);
	if (!expectCopied && !same) KNOWN("[%s] doc keeps a POINTER into the Lua string (not copied): output changes once Lua collects it; fine only while ProcessLuaResult serializes before popping", what);
	lua_close(L);
	for (size_t i = 0; i < g_quarantine.size(); i++) free(g_quarantine[i]);
	g_quarantine.clear();
}
TEST(lifetime_value_string)   { lifetimeCheck("string value", "return ('v'):rep(20)..tostring(os.clock())", false); }
TEST(lifetime_string_in_array) { lifetimeCheck("string in array", "return {('v'):rep(20)..tostring(os.clock()), ('w'):rep(20)..tostring(os.clock())}", false); }
TEST(lifetime_string_key)      { lifetimeCheck("string key", "return {[('k'):rep(20)..tostring(os.clock())]=1}", false); }
TEST(lifetime_string_val_in_map) { lifetimeCheck("string value in map", "return {a=('v'):rep(20)..tostring(os.clock())}", false); }
TEST(lifetime_number_key)      { lifetimeCheck("number key", "return {[1.5]=true,[2.5]=true}", true); }
TEST(lifetime_type_names)      { lifetimeCheck("function/userdata names", "return {print, io.stdout, coroutine.create(function() end)}", true); }
TEST(lifetime_nested_numkey_value) { lifetimeCheck("nested string key under a numeric key", "return {[1.5]={x=1}}", false); }

// ===== stack-pressure =====
static void fillStack(lua_State* L, int target)
{
	int need = target - lua_gettop(L);
	if (need > 0 && !lua_checkstack(L, need + 8)) { FAIL("cannot grow stack to %d", target); return; }
	while (lua_gettop(L) < target) lua_pushnil(L);
}
TEST(lua_stack_nearly_full_to_json)
{
	// LUAI_MAXCSTACK is 8000: fill to 7985 so a 20-deep table runs out of stack part-way down
	lua_State* L = newState();
	luaL_loadstring(L, "local t={} local c=t for i=2,20 do local n={} c[1]=n c=n end return t");
	lua_pcall(L, 0, 1, 0);
	int tbl = lua_gettop(L);
	fillStack(L, 7985);
	int top = lua_gettop(L);
	DynamicJsonDocument doc(65536); doc["type"] = "t";
	g_logs.clear();
	g_svc.ConvertLuaToJsonValue(L, tbl, doc.as<JsonObject>(), "result");
	std::string j; serializeJson(doc, j);
	if (lua_gettop(L) != top) FAIL("stack leak %d -> %d", top, lua_gettop(L));
	printf("nearly full stack (top=%d) -> %s | too-deep log=%d\n", top, trunc(j, 120).c_str(), (int)warned("too deep"));
	if (!warned("too deep")) FAIL("expected the stack-full path (too deep) to trigger");
	lua_close(L);
}

// ===== JSON -> Lua =====
static std::string luaEval(lua_State* L, const char* expr)
{
	std::string chunk = std::string("return ") + expr;
	if (luaL_loadstring(L, chunk.c_str()) || lua_pcall(L, 0, 1, 0)) { std::string e = lua_tostring(L, -1); lua_pop(L, 1); return "LUAERR:" + e; }
	size_t len; const char* s = lua_tolstring(L, -1, &len); std::string r(s ? s : "", s ? len : 0); lua_pop(L, 1); return r;
}
// Parse text with the given nesting limit, convert to Lua, bind result as global G. Returns false on parse error.
static bool jsonToLua(lua_State* L, const std::string& text, int nestingLimit, std::string* parseErr = 0)
{
	DynamicJsonDocument doc(text.size() * 40 + 65536);
	DeserializationError e = deserializeJson(doc, text, DeserializationOption::NestingLimit(nestingLimit));
	if (e) { if (parseErr) *parseErr = e.c_str(); return false; }
	int before = lua_gettop(L);
	g_svc.ConvertJsonToLuaValue(L, doc.as<JsonVariant>());
	if (lua_gettop(L) != before + 1) FAIL("ConvertJsonToLuaValue pushed %d values (expected 1) for %s", lua_gettop(L) - before, trunc(text).c_str());
	lua_setglobal(L, "G");
	lua_settop(L, before);
	return true;
}
static void deepJson(int N, bool obj, const char* expect, const char* name)
{
	// built through the ArduinoJson API: its text parser takes at most 255 levels (NestingLimit is uint8_t)
	DynamicJsonDocument doc(N * 64 + 65536);
	if (obj) { JsonObject o = doc.to<JsonObject>(); for (int i = 1; i < N; i++) o = o.createNestedObject("a"); o["a"] = 0; }
	else { JsonArray a = doc.to<JsonArray>(); for (int i = 1; i < N; i++) a = a.createNestedArray(); a.add(0); }
	if (doc.overflowed()) { FAIL("[%s] test doc overflowed", name); return; }
	lua_State* L = newState(); g_logs.clear();
	int before = lua_gettop(L);
	g_svc.ConvertJsonToLuaValue(L, doc.as<JsonVariant>());
	if (lua_gettop(L) != before + 1) FAIL("[%s] pushed %d values", name, lua_gettop(L) - before);
	lua_setglobal(L, "G");
	std::string got = luaEval(L, obj ? "(function() local d=0 local t=G while type(t)=='table' do d=d+1 t=t.a end return d..':'..tostring(t) end)()"
	                                 : "(function() local d=0 local t=G while type(t)=='table' do d=d+1 t=t[1] end return d..':'..tostring(t) end)()");
	if (got != expect) FAIL("[%s] expected %s got %s", name, expect, got.c_str());
	if (N >= 33 && !warned("too deep")) FAIL("[%s] no too-deep warning logged", name);
	lua_close(L);
}
TEST(json_text_nesting_255_vs_256)
{
	// the text parser (as used for the wire) cannot take what the converter's cap of 32 would allow beyond 255; just document
	DynamicJsonDocument doc(65536);
	DeserializationError e = deserializeJson(doc, rep("[", 100) + "0" + rep("]", 100), DeserializationOption::NestingLimit(255));
	if (e) FAIL("100-deep with limit 255: %s", e.c_str());
}
TEST(json_deep_array_31)   { deepJson(31, false, "31:0", "arr31"); }
TEST(json_deep_array_32)   { deepJson(32, false, "32:0", "arr32"); }
TEST(json_deep_array_33)   { deepJson(33, false, "32:nil", "arr33"); }
TEST(json_deep_array_1000) { deepJson(1000, false, "32:nil", "arr1000"); }
TEST(json_deep_object_32)  { deepJson(32, true, "32:0", "obj32"); }
TEST(json_deep_object_33)  { deepJson(33, true, "32:nil", "obj33"); }
TEST(json_deep_object_1000){ deepJson(1000, true, "32:nil", "obj1000"); }
TEST(json_default_nesting_limit)
{
	// deserializeJson (as RouteMessage/SendMessage paths call it) uses ARDUINOJSON_DEFAULT_NESTING_LIMIT=10
	std::string text = rep("[", 11) + "0" + rep("]", 11), err;
	DynamicJsonDocument doc(65536);
	DeserializationError e = deserializeJson(doc, text);
	if (e) KNOWN("deserializeJson with the default nesting limit rejects 11-deep JSON (%s), so the depth-32 cap in ConvertJsonToLuaValue is unreachable from the wire; lua_call args / external_call replies nested deeper than 10 fail", e.c_str());
}
TEST(json_huge_array)
{
	lua_State* L = newState();
	std::string t = "["; for (int i = 1; i <= 200000; i++) { if (i > 1) t += ","; t += itos(i); } t += "]";
	if (!jsonToLua(L, t, 10)) { FAIL("parse"); return; }
	std::string g = luaEval(L, "#G..':'..G[1]..':'..G[200000]");
	if (g != "200000:1:200000") FAIL("huge array: %s", g.c_str());
	lua_close(L);
}
TEST(json_huge_object)
{
	lua_State* L = newState();
	std::string t = "{"; for (int i = 1; i <= 5000; i++) { if (i > 1) t += ","; t += "\"k" + itos(i) + "\":" + itos(i); } t += "}";
	if (!jsonToLua(L, t, 10)) { FAIL("parse"); return; }
	std::string g = luaEval(L, "(function() local n=0 for _ in pairs(G) do n=n+1 end return n..':'..G.k5000 end)()");
	if (g != "5000:5000") FAIL("huge object: %s", g.c_str());
	lua_close(L);
}
TEST(json_wide_nested_arrays)
{
	lua_State* L = newState();
	std::string t = "["; for (int i = 1; i <= 20000; i++) { if (i > 1) t += ","; t += "[" + itos(i) + ",[1]]"; } t += "]";
	if (!jsonToLua(L, t, 10)) { FAIL("parse"); return; }
	std::string g = luaEval(L, "#G..':'..G[20000][1]");
	if (g != "20000:20000") FAIL("wide: %s", g.c_str());
	if (lua_gettop(L) != 0) FAIL("leak");
	lua_close(L);
}
TEST(json_scalars)
{
	struct { const char* json; const char* expr; const char* want; } k[] = {
		{ "null", "tostring(G)", "nil" }, { "true", "tostring(G)", "true" }, { "false", "tostring(G)", "false" },
		{ "0", "tostring(G)", "0" }, { "-5", "tostring(G)", "-5" }, { "1.5", "tostring(G)", "1.5" },
		{ "\"x\"", "G", "x" }, { "\"\"", "G", "" }, { "[]", "type(G)..#G", "table0" }, { "{}", "type(G)..tostring(next(G))", "tablenil" },
		{ "[null,1]", "tostring(G[1])..G[2]", "nil1" }, { "{\"a\":null,\"b\":2}", "tostring(G.a)..G.b", "nil2" },
		{ "{\"\":1}", "G['']", "1" }, { "\"a\\\"b\\\\c\\n\"", "G", "a\"b\\c\n" },
		{ "\"\\u00e9\"", "#G", "2" }, { "\"\\ud83d\\ude00\"", "#G", "4" }, { "\"\\u20ac\"", "#G", "3" },
		{ 0, 0, 0 } };
	for (int i = 0; k[i].json; i++) {
		lua_State* L = newState();
		if (!jsonToLua(L, k[i].json, 10)) { FAIL("parse %s", k[i].json); lua_close(L); continue; }
		std::string got = luaEval(L, k[i].expr);
		if (got != k[i].want) FAIL("json %s -> %s : expected %s got %s", k[i].json, k[i].expr, k[i].want, trunc(got).c_str());
		lua_close(L);
	}
}
TEST(json_unicode_edge)
{
	struct { const char* json; const char* ideal; } k[] = {
		{ "\"a\\u0000b\"", "3" },       // embedded NUL: lua_pushstring truncates at it
		{ "\"\\ud800\"", "valid" },     // lone surrogate
		{ "\"\\udc00\"", "valid" },
		{ "\"\\ud83d\"", "valid" },
		{ 0, 0 } };
	for (int i = 0; k[i].json; i++) {
		lua_State* L = newState(); std::string err;
		if (!jsonToLua(L, k[i].json, 10, &err)) { KNOWN("json %s rejected by parser: %s", k[i].json, err.c_str()); lua_close(L); continue; }
		std::string len = luaEval(L, "#G");
		if (!strcmp(k[i].ideal, "3")) { if (len != "3") KNOWN("json %s: Lua string length %s (ideal 3): embedded NUL truncates the string", k[i].json, len.c_str()); }
		else { std::string hex = luaEval(L, "(function() local t={} for i=1,#G do t[#t+1]=string.format('%02x',G:byte(i)) end return table.concat(t) end)()");
			if (g_verbose) printf("lone surrogate %s -> bytes %s\n", k[i].json, hex.c_str());
			std::string raw = luaEval(L, "G"); if (!validUtf8(raw)) KNOWN("json %s -> Lua string is not valid UTF-8 (bytes %s)", k[i].json, hex.c_str()); }
		lua_close(L);
	}
}
TEST(json_numbers)
{
	const char* nums[] = { "1e400", "-1e400", "1e-400", "2147483647", "2147483648", "-2147483649", "4294967295", "4294967296",
		"18446744073709551615", "18446744073709551616", "9007199254740993", "123456789012345678901234567890", "0.1", "-0", "1E2", "1e308", "5e-324", 0 };
	for (int i = 0; nums[i]; i++) {
		lua_State* L = newState(); std::string err;
		std::string text = std::string("[") + nums[i] + "]";
		if (!jsonToLua(L, text, 10, &err)) { KNOWN("number %s rejected by parser: %s", nums[i], err.c_str()); lua_close(L); continue; }
		std::string ty = luaEval(L, "type(G[1])");
		double want = strtod(nums[i], 0);
		double got = 0; bool isnum = (ty == "number");
		if (isnum) { lua_getglobal(L, "G"); lua_rawgeti(L, -1, 1); got = lua_tonumber(L, -1); lua_pop(L, 2); }
		bool same = isnum && ((want - want) != 0 ? (got - got) != 0 && (got > 0) == (want > 0) : got == want);
		if (g_verbose) printf("number %s -> %s %.17g (strtod %.17g)\n", nums[i], ty.c_str(), got, want);
		if (!same) KNOWN("number %s -> Lua %s %.17g, strtod says %.17g", nums[i], ty.c_str(), got, want);
		lua_close(L);
	}
}
TEST(json_stack_nearly_full)
{
	lua_State* L = newState();
	fillStack(L, 7985);
	std::string text = rep("[", 20) + "0" + rep("]", 20);
	DynamicJsonDocument doc(65536); deserializeJson(doc, text, DeserializationOption::NestingLimit(100));
	int before = lua_gettop(L);
	g_logs.clear();
	g_svc.ConvertJsonToLuaValue(L, doc.as<JsonVariant>());
	if (lua_gettop(L) != before + 1) FAIL("pushed %d values", lua_gettop(L) - before);
	printf("nearly full stack: top %d -> %d, result type %s, too-deep log=%d\n", before, lua_gettop(L), lua_typename(L, lua_type(L, -1)), (int)warned("too deep"));
	if (!warned("too deep")) FAIL("expected the stack-full path to trigger");
	lua_close(L);
}
TEST(json_to_lua_then_back)
{
	// round trip of typical payloads
	const char* texts[] = { "{\"a\":[1,2,{\"b\":\"c\"}],\"d\":null,\"e\":true,\"f\":1.25}", "[[],{}]", "[1,[2,[3,[4]]]]", 0 };
	for (int i = 0; texts[i]; i++) {
		DynamicJsonDocument in(8192);
		deserializeJson(in, texts[i]);
		lua_State* L = newState();
		g_svc.ConvertJsonToLuaValue(L, in.as<JsonVariant>());
		DynamicJsonDocument out(8192); out["type"] = "t";
		g_svc.ConvertLuaValuesInDocument(L, 1, 1, out, "result");
		DynamicJsonDocument expect(8192); deserializeJson(expect, texts[i]);
		// Lua loses null members in objects and may reorder keys; compare parsed values for the arrays-only text
		std::string a; serializeJson(out["result"], a);
		if (g_verbose) printf("roundtrip %s -> %s\n", texts[i], a.c_str());
		if (i == 1 && a != texts[i]) KNOWN("roundtrip %s -> %s: an empty JSON array comes back as {} (an empty Lua table is always an object)", texts[i], a.c_str());
		else if (i > 1 && a != texts[i]) FAIL("roundtrip %s -> %s", texts[i], trunc(a).c_str());
		if (lua_gettop(L) != 1) FAIL("leak");
		lua_close(L);
	}
}

// ---- runner ----
static std::vector<std::string> g_known;

static int runChild(const Test& t, FILE* out)
{
	fflush(NULL);
	pid_t pid = fork();
	if (pid == 0) {
		fflush(stdout);
		dup2(fileno(out), 1); dup2(fileno(out), 2);
		alarm(15);
		g_failed = false;
		if (t.caseIdx >= 0) {
			Case c = cases()[t.caseIdx];
			c.name = caseStore()[t.caseIdx * 3].c_str(); c.chunk = caseStore()[t.caseIdx * 3 + 1].c_str(); c.expect = caseStore()[t.caseIdx * 3 + 2].c_str();
			runCase(c);
		} else t.fn();
		fflush(stdout); fflush(stderr);
		exit(g_failed ? 1 : 0);
	}
	int st = 0; waitpid(pid, &st, 0);
	if (WIFEXITED(st)) return WEXITSTATUS(st);
	return 1000 + (WIFSIGNALED(st) ? WTERMSIG(st) : 0);
}

int main(int argc, char** argv)
{
	const char* filter = 0;
	for (int i = 1; i < argc; i++) { if (!strcmp(argv[i], "-v")) g_verbose = true; else filter = argv[i]; }
	registerSimpleCases(); registerNestCases();
	for (size_t i = 0; i < cases().size(); i++) { Test t; t.name = caseStore()[i * 3]; t.fn = 0; t.caseIdx = (int)i; tests().push_back(t); }
	int total = 0, failed = 0, known = 0;
	for (size_t i = 0; i < tests().size(); i++) {
		const Test& t = tests()[i];
		if (filter && t.name.find(filter) == std::string::npos) continue;
		total++;
		FILE* out = tmpfile();
		int rc = runChild(t, out);
		fflush(out); rewind(out);
		std::string text; char buf[4096]; size_t n;
		while ((n = fread(buf, 1, sizeof buf, out)) > 0) text.append(buf, n);
		fclose(out);
		// count/collect KNOWN lines
		bool hadKnown = false; size_t p = 0;
		while ((p = text.find("KNOWN: ", p)) != std::string::npos) {
			size_t e = text.find('\n', p); std::string line = text.substr(p + 7, e == std::string::npos ? std::string::npos : e - p - 7);
			g_known.push_back(t.name + ": " + line); hadKnown = true; p = (e == std::string::npos) ? text.size() : e;
		}
		if (hadKnown) known++;
		if (rc != 0) {
			failed++;
			std::string why = rc == 1 ? "FAILED" : rc == 1006 ? "ABORT/SANITIZER" : rc == 1014 ? "TIMEOUT (15s)" : rc == 1011 ? "SEGFAULT" : "EXIT " + itos(rc);
			printf("=== %s: %s ===\n", t.name.c_str(), why.c_str());
			// show the first 25 lines of output
			size_t pos = 0; int lines = 0;
			while (pos < text.size() && lines < 25) { size_t e = text.find('\n', pos); if (e == std::string::npos) e = text.size(); printf("  %s\n", text.substr(pos, e - pos).c_str()); pos = e + 1; lines++; }
		} else if (g_verbose) {
			printf("ok   %s\n", t.name.c_str());
			size_t pos = 0; while (pos < text.size()) { size_t e = text.find('\n', pos); if (e == std::string::npos) e = text.size(); if (e > pos) printf("       %s\n", text.substr(pos, e - pos).c_str()); pos = e + 1; }
		}
	}
	if (g_verbose || !g_known.empty()) {
		printf("--- known deviations (not failures; see README) ---\n");
		for (size_t i = 0; i < g_known.size(); i++) printf("  %s\n", g_known[i].c_str());
	}
	printf("SUMMARY: %d tests, %d failed, %d with known deviations (%s, sizeof(void*)=%d)\n", total, failed, known, "ASAN+UBSAN", (int)sizeof(void*));
	return failed ? 1 : 0;
}
